const {chromium}=require('/private/tmp/bokushi-japan-replay/node_modules/playwright');
const assert=require('node:assert/strict');
const base='http://localhost:4482/trips/japan-2025/play#d4-4';
(async()=>{
 const b=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--enable-unsafe-swiftshader']});
 try {
 for(const isolate of [false,true]){
  const p=await b.newPage({viewport:{width:1000,height:720},reducedMotion:'reduce'});
  await p.goto(base,{waitUntil:'domcontentloaded'});
  const panel=p.locator('[data-trip-map-panel]');const image=panel.locator('.trip-map-card__photo-link').first();
  await image.waitFor({timeout:35000});await image.click();
  const dialog=p.locator('dialog.lightbox[open]');await dialog.waitFor();
  const count=dialog.locator('[data-lightbox-counter]');
  await p.waitForFunction(()=>!!document.querySelector('dialog.lightbox[open] [data-lightbox-counter]')?.textContent);
  const initial=await count.innerText();const before=await p.evaluate(()=>location.hash);
  if(isolate)await dialog.evaluate(el=>el.addEventListener('keydown',e=>{
   e.stopPropagation();const sel={ArrowRight:'[data-lightbox-next]',ArrowLeft:'[data-lightbox-prev]',Escape:'.lightbox__close'}[e.key];
   if(sel){e.preventDefault();el.querySelector(sel).click()}
  }));
  await p.keyboard.press('ArrowRight');
  await p.waitForFunction(value=>document.querySelector('dialog.lightbox[open] [data-lightbox-counter]')?.textContent!==value,initial);
  const after=await p.evaluate(()=>location.hash);const next=await count.innerText();
  console.log(isolate?'isolated':'current',{initial,next,before,after,stillOpen:await dialog.count(),underlyingTitle:(await panel.locator('[data-trip-map-title]').allTextContents()).join('')});
  if(isolate){assert.equal(after,before);await p.keyboard.press('Escape');await p.waitForTimeout(150);assert.equal(await dialog.count(),0);assert.equal(await p.evaluate(()=>location.hash),before);await p.keyboard.press('ArrowRight');await p.waitForFunction(x=>location.hash!==x,before);console.log('Esc only closed lightbox; next ArrowRight changed underlying journey after close');}
  await p.close();
 }
 }finally{await b.close()}
})().catch(e=>{console.error(e.message.replace(/pk\\.[\\w.-]+/g,'<redacted>'));process.exit(1)});
