        function arrive(point: TripLocation, mode: TravelMode) {
            if (previous) legModes.push(mode);
            points.push(point);
            previous = point;
        }
        for (const [fromName, toName] of stop.rail ?? []) {
            const from = station(fromName);
            const to = station(toName);
            if (!routes[getTrainLegKey(from, to)]) {
                throw new Error(`Missing railway: ${fromName} → ${toName}`);
            }
            if (previous?.id !== from.id) arrive(from, stop.approachBy === "bus" ? "bus" : "visit");
            arrive(to, "train");
        }
        if (points.length && previous?.id === destination.id) {
            points[points.length - 1] = destination;
        } else {
            const mode = stop.rail ? "visit" : (stop.arrivedBy ?? "visit");
            if (
                mode !== "train" &&
                mode !== "bus" &&
                mode !== "visit" &&
                mode !== "plane" &&
                mode !== "car"
