            viewDayMoments: "查看照片或当天游记",
        },
    });
    window.addEventListener(
        "pagehide",
        (event) => {
            if (!event.persisted) map.destroy();
        },
        { once: true },
    );
}
const page = document.querySelector<HTMLElement>("[data-trip-map]");
if (page) void mount(page);
